def asignar_permisos(apps, schema_editor):
    alias = schema_editor.connection.alias
    tipos = apps.get_model("contenttypes", "ContentType").objects.using(alias)
    permisos = apps.get_model("auth", "Permission").objects.using(alias)
    grupo, _ = (
        apps.get_model("auth", "Group")
        .objects.using(alias)
        .get_or_create(name="Administrador")
    )
    for modelo, codigo in PERMISOS.items():
        tipo, _ = tipos.get_or_create(app_label="inventario", model=modelo)
        nombre = dict(apps.get_model("inventario", modelo)._meta.permissions)[codigo]
        permiso, _ = permisos.get_or_create(
            content_type=tipo, codename=codigo, defaults={"name": nombre}
        )
        grupo.permissions.add(permiso)


def retirar_permisos(apps, schema_editor):
    alias = schema_editor.connection.alias
    cuentas = apps.get_model("inventario", "CuentaPorCobrar").objects.using(alias)
    pagos = apps.get_model("inventario", "PagoCliente").objects.using(alias)
    if (
        cuentas.filter(fiado_seguro=True).exists()
        or cuentas.filter(fecha_vencimiento__isnull=True).exists()
        or pagos.filter(clave__isnull=False).exists()
    ):
        raise RuntimeError(
            "El esquema 0021 no conserva los vínculos y claves de STK-07A. Conserva 0022."
        )
    apps.get_model("auth", "Permission").objects.using(alias).filter(
        content_type__app_label="inventario", codename__in=PERMISOS.values()
    ).delete()


